import{_ as e,H as r,f as a,i as l}from"./chunks/framework.DLd0CbzH.js";const m=JSON.parse('{"title":"Лицензии и ограничения","description":"Тарифные планы OmniCraft ERP, работа Free-лимита, защита данных и активация лицензионных ключей.","frontmatter":{"title":"Лицензии и ограничения","description":"Тарифные планы OmniCraft ERP, работа Free-лимита, защита данных и активация лицензионных ключей.","order":14},"headers":[],"relativePath":"ru/docs/licenses.md","filePath":"ru/docs/licenses.md"}'),n={name:"ru/docs/licenses.md"};function i(s,t,o,d,c,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку OmniCraft ERP сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🔐-лицензии-и-ограничения" tabindex="-1">🔐 Лицензии и ограничения <a class="header-anchor" href="#🔐-лицензии-и-ограничения" aria-label="Permalink to &quot;🔐 Лицензии и ограничения&quot;">​</a></h1><p>OmniCraft ERP распространяется по модели <strong>Shareware с честным триалом</strong>. Вы можете скачать программу, настроить её под себя и вести полноценный учет совершенно бесплатно, пока ваш бизнес не выйдет на стабильные обороты.</p><p>На этой странице подробно описано, как работают тарифные планы, почему Free-версия имеет именно такие рамки и как устроена автономная криптографическая защита программы.</p><hr><h2 id="📊-три-тарифных-плана" tabindex="-1">📊 Три тарифных плана <a class="header-anchor" href="#📊-три-тарифных-плана" aria-label="Permalink to &quot;📊 Три тарифных плана&quot;">​</a></h2><p>Программа предлагает простую и прозрачную градацию возможностей, которая растет вместе с вашим бизнесом.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Функция / Возможность</th><th style="text-align:center;">🆓 Free (0 ₽)</th><th style="text-align:center;">🥈 Standard</th><th style="text-align:center;">👑 PRO</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Все рабочие вкладки</strong> (Мастерская, Сырьё, Калькулятор, Верстак, Витрина, ДДС, Капитал, Аналитика)</td><td style="text-align:center;">✅ Полностью</td><td style="text-align:center;">✅ Полностью</td><td style="text-align:center;">✅ Полностью</td></tr><tr><td style="text-align:left;"><strong>Лимит на проведение продаж</strong></td><td style="text-align:center;">⚠️ До 20 чеков</td><td style="text-align:center;">♾️ Безлимит</td><td style="text-align:center;">♾️ Безлимит</td></tr><tr><td style="text-align:left;"><strong>Авто-бэкапы и безопасность (WAL, GFS)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Создание Мультипространств</strong> (несколько БД)</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Глобальная вкладка «Мой капитал»</strong> (Личные финансы)</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Сквозные тематические модули</strong> (Add-ons)</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (докупка)</td><td style="text-align:center;">✅ (докупка)</td></tr></tbody></table><hr><h2 id="🆓-как-работает-free-лимит-20-продаж" tabindex="-1">🆓 Как работает Free-лимит (20 продаж) <a class="header-anchor" href="#🆓-как-работает-free-лимит-20-продаж" aria-label="Permalink to &quot;🆓 Как работает Free-лимит (20 продаж)&quot;">​</a></h2><p>Бесплатная версия OmniCraft ERP не урезана по функционалу — вам доступны абсолютно все инструменты аналитики, планирования и складского учета. Ограничение касается только <strong>финальной точки конвейера</strong>: регистрации факта получения денег от клиента.</p><h3 id="что-происходит-при-достижении-лимита" tabindex="-1">Что происходит при достижении лимита? <a class="header-anchor" href="#что-происходит-при-достижении-лимита" aria-label="Permalink to &quot;Что происходит при достижении лимита?&quot;">​</a></h3><p>Как только счетчик пробитых чеков (во вкладке «Продажи») достигает <strong>20 штук</strong>, программа автоматически переходит в безопасный режим <strong>Read-Only (Только чтение)</strong>.</p><ul><li>🚫 <strong>Блокируются действия:</strong> Кнопки «Провести продажу» во вкладке <em>Продажи</em> и «Завершить пошив» во вкладке <em>Производство</em> становятся неактивными. На экране появляется красное предупреждение с просьбой активировать лицензию.</li><li>✅ <strong>Сохраняется доступ:</strong> Вы можете беспрепятственно просматривать всю аналитику, запускать партии на верстак, закупать сырьё, создавать новые рецепты, смотреть графики и делать резервные копии.</li><li>🔄 <strong>История не теряется:</strong> Все ваши данные, наработки и базы рецептов остаются с вами. Вы можете купить ключ в любой момент, ввести его в Настройках, и лимит будет мгновенно снят без потери истории.</li></ul><h3 id="🛡️-психологическии-предохранитель-от-обхода" tabindex="-1">🛡️ Психологический предохранитель от обхода <a class="header-anchor" href="#🛡️-психологическии-предохранитель-от-обхода" aria-label="Permalink to &quot;🛡️ Психологический предохранитель от обхода&quot;">​</a></h3><p>В отличие от многих программ, где пользователи пытаются «обнулить» триал удалением тестовых записей, в OmniCraft ERP это <strong>экономически бессмысленно</strong>.</p><p>Вся ценность программы строится на непрерывности исторических данных. Если вы вручную удалите старые чеки или сбросите историю продаж, чтобы обойти лимит, вы <strong>полностью разрушите</strong>:</p><ol><li>Свой управленческий баланс (Капитал).</li><li>Историю движения средств (ДДС).</li><li>Графики выручки и расчет Точки безубыточности в Аналитике.</li><li>Точность FIFO-себестоимости на складе готовой продукции.</li></ol><p>Таким образом, пользователь сам экономически заинтересован в чистоте и непрерывности своей базы данных. Покупка лицензии — это не «разблокировка софта», а инвестиция в сохранение цифрового фундамента вашего бизнеса.</p><hr><h2 id="🛠-техническая-архитектура-защиты-офлаин-проверка" tabindex="-1">🛠 Техническая архитектура защиты (Офлайн-проверка) <a class="header-anchor" href="#🛠-техническая-архитектура-защиты-офлаин-проверка" aria-label="Permalink to &quot;🛠 Техническая архитектура защиты (Офлайн-проверка)&quot;">​</a></h2><p>OmniCraft ERP — это локальное десктопное приложение. Мы принципиально не используем облачные базы данных для хранения ваших финансовых операций, поэтому проверка лицензии должна быть полностью <strong>автономной</strong> и работать без подключения к интернету.</p><h3 id="_1-отпечаток-железа-hwid" tabindex="-1">1. Отпечаток железа (HWID) <a class="header-anchor" href="#_1-отпечаток-железа-hwid" aria-label="Permalink to &quot;1. Отпечаток железа (HWID)&quot;">​</a></h3><p>При первом запуске программа генерирует уникальный идентификатор вашего компьютера (Hardware ID). Он создается на базе зашифрованного (хешированного) UUID материнской платы и системных параметров ОС.</p><ul><li><strong>Приватность:</strong> HWID — это просто набор символов (например, <code>A1B2-C3D4-E5F6-G7H8</code>). Он не содержит ваших личных данных, IP-адресов или имен файлов.</li><li><strong>Назначение:</strong> Лицензионный ключ жестко привязывается к этому отпечатку. Один ключ можно активировать только на том компьютере, для которого он был выпущен.</li></ul><h3 id="_2-асимметричное-шифрование-rsa" tabindex="-1">2. Асимметричное шифрование (RSA) <a class="header-anchor" href="#_2-асимметричное-шифрование-rsa" aria-label="Permalink to &quot;2. Асимметричное шифрование (RSA)&quot;">​</a></h3><p>Для защиты от взлома и подделки ключей используется криптография с открытым ключом:</p><ul><li>В исходном коде программы зашит только <strong>Публичный ключ RSA</strong>. Он умеет только <em>проверять</em> подписи, но не умеет их создавать.</li><li><strong>Закрытый ключ RSA</strong> хранится исключительно на защищенном сервере биллинга (Cloudflare Workers) и никогда не попадает в дистрибутив программы.</li></ul><h3 id="_3-как-выглядит-процесс-активации" tabindex="-1">3. Как выглядит процесс активации? <a class="header-anchor" href="#_3-как-выглядит-процесс-активации" aria-label="Permalink to &quot;3. Как выглядит процесс активации?&quot;">​</a></h3><ol><li>Вы оплачиваете лицензию на сайте. Сервер считывает ваш HWID и генерирует JSON-файл с параметрами (тариф, статус PRO, список купленных модулей).</li><li>Сервер подписывает этот JSON своим Закрытым ключом и выдает вам длинную Base64-строку (ваш Лицензионный ключ).</li><li>Вы вставляете эту строку во вкладке <strong>«Настройки»</strong> в поле «Лицензионный ключ».</li><li>Программа расшифровывает строку, проверяет цифровую подпись Публичным ключом и сверяет HWID. Если всё совпадает — функционал разблокируется мгновенно.</li></ol><hr><h2 id="🕵️-анонимность-и-безопасность-обход-фз-152" tabindex="-1">🕵️ Анонимность и безопасность (Обход ФЗ-152) <a class="header-anchor" href="#🕵️-анонимность-и-безопасность-обход-фз-152" aria-label="Permalink to &quot;🕵️ Анонимность и безопасность (Обход ФЗ-152)&quot;">​</a></h2><p>Мы с огромным уважением относимся к приватности пользователей и закону РФ №152 «О персональных данных». Архитектура биллинга OmniCraft спроектирована так, чтобы <strong>вообще не собирать ваши персональные данные</strong>.</p><h3 id="модель-«анонимного-лицензионного-токена»" tabindex="-1">Модель «Анонимного Лицензионного Токена» <a class="header-anchor" href="#модель-«анонимного-лицензионного-токена»" aria-label="Permalink to &quot;Модель «Анонимного Лицензионного Токена»&quot;">​</a></h3><ul><li>При покупке на сайте не требуется регистрация с почтой, телефоном или паспортом.</li><li>Система генерирует случайный анонимный токен вида <code>LIC-XXXX-XXXX</code>.</li><li>В базе сервера хранится только обезличенная запись: <code>[Токен] | [Тип лицензии] | [Список активных HWID]</code>.</li></ul><h3 id="🔄-self-service-перенос-лицензии-на-новыи-пк" tabindex="-1">🔄 Self-Service: Перенос лицензии на новый ПК <a class="header-anchor" href="#🔄-self-service-перенос-лицензии-на-новыи-пк" aria-label="Permalink to &quot;🔄 Self-Service: Перенос лицензии на новый ПК&quot;">​</a></h3><p>Что делать, если ваш компьютер сломался или вы купили новый ноутбук? Поскольку мы не храним ваших email-адресов, вы не сможете написать в «поддержку» с просьбой сбросить привязку. Вместо этого работает система самообслуживания:</p><ol><li>Вы заходите на сайт OmniCraft в раздел управления лицензиями.</li><li>Вводите свой анонимный токен <code>LIC-XXXX-XXXX</code>, который пришел вам при покупке.</li><li>Система показывает список «железа», к которому сейчас привязан ключ, и позволяет вам <strong>самостоятельно отвязать</strong> старый или сгоревший компьютер, чтобы освободить слот для нового HWID.</li></ol><hr><h2 id="⚙️-где-посмотреть-свои-hwid-и-активировать-ключ" tabindex="-1">⚙️ Где посмотреть свой HWID и активировать ключ? <a class="header-anchor" href="#⚙️-где-посмотреть-свои-hwid-и-активировать-ключ" aria-label="Permalink to &quot;⚙️ Где посмотреть свой HWID и активировать ключ?&quot;">​</a></h2><p>Все операции с лицензией проводятся во вкладке <strong>«Настройки»</strong> (раздел <em>Управление лицензией</em>).</p><ol><li><strong>Идентификатор (HWID):</strong> Программа автоматически вычисляет его и отображает в верхней части карточки. Нажмите на иконку копирования 📋, чтобы отправить его на сайт при оформлении покупки.</li><li><strong>Статус лицензии:</strong> Здесь вы всегда видите текущий режим работы программы (<em>Free-версия</em>, <em>Standard</em> или <em>PRO</em>).</li><li><strong>Активация:</strong> Вставьте скопированный Base64-ключ в поле ввода и нажмите кнопку <strong>«Активировать»</strong>. Программа проверит подпись и перезапишет статус в локальной базе данных.</li></ol><div class="tip custom-block"><p class="custom-block-title">Динамический заголовок окна</p><p>Как только вы активируете лицензию, заголовок окна Windows мгновенно изменится. Вместо стандартного <em>OmniCraft ERP</em> там появится гордая приписка: <em>OmniCraft ERP (License Pro)</em> или <em>OmniCraft ERP (License, Modules [2])</em>, если вы докупали сквозные модули.</p></div>',43)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
